files.examples/01_column_order.sql:
-- LEARN(sql.indexes.composite): equality columns first, then the range or sort column.
CREATE TABLE orders (
  id        bigint PRIMARY KEY,
  shop_id   int NOT NULL,
  placed_on date NOT NULL,
  total     numeric(10,2) NOT NULL
);
-- 100 shops, 100 orders a day for 200 days: one order per shop per day.
INSERT INTO orders
SELECT g, g % 100 + 1, date '2026-01-01' + g / 100, g % 500 + 0.99
FROM generate_series(0, 19999) AS g;
ANALYZE orders;

-- The question: shop 7's orders in March and April.
SELECT count(*) FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';

-- Range column first: the scan covers two months of every shop's entries.
CREATE INDEX orders_day_shop ON orders (placed_on, shop_id);
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
DROP INDEX orders_day_shop;

-- Equality column first: shop 7's entries are adjacent, already sorted by day.
CREATE INDEX orders_shop_day ON orders (shop_id, placed_on);
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';

-- The same index serves the leading column alone, in index order...
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE shop_id = 7 ORDER BY placed_on DESC LIMIT 10;

-- ...but a sort on a column it doesn't hold still needs a Sort.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE shop_id = 7 ORDER BY total DESC LIMIT 10;

files.examples/02_partial_expression.sql:
CREATE TABLE tickets (
  id        bigint PRIMARY KEY,
  status    text NOT NULL,
  opened_on date NOT NULL,
  city      text NOT NULL
);
-- 2% open, the rest closed; city names arrive in capitals from an import.
INSERT INTO tickets
SELECT g,
       CASE WHEN g % 50 = 0 THEN 'open' ELSE 'closed' END,
       date '2026-01-01' + g / 100,
       (ARRAY['ISPARTA', 'IĞDIR', 'İZMİR', 'ANKARA'])[g % 4 + 1] || '-' || g
FROM generate_series(1, 20000) AS g;
ANALYZE tickets;

-- Partial: only rows matching the WHERE get an entry.
CREATE INDEX tickets_opened ON tickets (opened_on);
CREATE INDEX tickets_open_opened ON tickets (opened_on) WHERE status = 'open';
SELECT pg_relation_size('tickets_opened') / 8192 AS full_pages,
       pg_relation_size('tickets_open_opened') / 8192 AS partial_pages;

-- The query states the index's condition, so the planner can use it.
EXPLAIN (COSTS OFF)
SELECT id FROM tickets WHERE status = 'open' ORDER BY opened_on LIMIT 10;

-- Expression: index what the query compares, here Turkish lower-casing.
SELECT lower('ISPARTA') AS default_rules,
       lower('ISPARTA' COLLATE "tr-x-icu") AS turkish_rules;
CREATE INDEX tickets_city_tr ON tickets (lower(city COLLATE "tr-x-icu"));
ANALYZE tickets;

-- Same expression as the index, collation included: index scan, one match.
EXPLAIN (COSTS OFF)
SELECT id, city FROM tickets WHERE lower(city COLLATE "tr-x-icu") = 'ısparta-8';
SELECT id, city FROM tickets WHERE lower(city COLLATE "tr-x-icu") = 'ısparta-8';

-- A different expression: no index, and no match under the default rules.
EXPLAIN (COSTS OFF)
SELECT id, city FROM tickets WHERE lower(city) = 'ısparta-8';
SELECT id, city FROM tickets WHERE lower(city) = 'ısparta-8';

